// org.site.list — E1 AC1. Generated by `pnpm gen:query`; guard case kept, acceptance case added.
// Row isolation for client users is proven in packages/db (site.rls.int.test.ts).
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, createTestDatabase, type TestDatabase } from '@ocs/testing';
import { Forbidden, openTestKernel, type TestKernel } from '../../kernel/index.ts';
import { createClient } from '../commands/create-client.ts';
import { createSite } from '../commands/create-site.ts';
import { siteList } from '../queries/site-list.ts';

const director = aStaffActor({ roles: ['director'] });
const other = aStaffActor();
let testDb: TestDatabase;
let t: TestKernel;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(director, createClient.permission, createSite.permission, siteList.permission);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.site.list', () => {
  it('refuses an actor without the permission', async () => {
    await expect(t.kernel.read(siteList, other, {})).rejects.toBeInstanceOf(Forbidden);
  });

  it('lists sites by Project ID, for one client or all', async () => {
    const ids: string[] = [];
    for (const shortCode of ['CLIENTB', 'CLIENTA']) {
      const c = await t.kernel.execute(createClient, director, { shortCode, name: shortCode }, 'test');
      ids.push(c.id);
      const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', standard: 'S' } as const;
      await t.kernel.execute(createSite, director, { clientId: c.id, name: 'Site 001', ...place }, 'test');
    }
    const all = await t.kernel.read(siteList, director, {});
    expect(all.map((s) => s.projectId)).toEqual(['CLIENTA-ES-MAD-001', 'CLIENTB-ES-MAD-001']);
    const onlyB = await t.kernel.read(siteList, director, { clientId: ids[0] });
    expect(onlyB).toEqual([
      expect.objectContaining({
        projectId: 'CLIENTB-ES-MAD-001',
        name: 'Site 001',
        standard: 'S',
        cityName: 'Madrid',
      }),
    ]);
  });
});
